import openpyxl
wb = openpyxl.load_workbook('EntireSummerSales.xlsx', read_only=True)
ws = wb.active
totals = {}
for row in ws.iter_rows(min_row=2, max_row=2001, values_only=True):
    if len(row) < 7:
        continue
    promo = row[3]  # Column D = Promotion
